// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/knowledge/topics", wrapper.ListKnowledgeTopics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/knowledge/topics/{topicId}/articles", wrapper.ListTopicArticles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/knowledge/articles/{articleId}", wrapper.GetArticle)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/staff/knowledge/topics", wrapper.StaffListTopics)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/staff/knowledge/topics", wrapper.StaffCreateTopic)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/staff/knowledge/articles", wrapper.StaffListArticles)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/staff/knowledge/articles", wrapper.StaffCreateDraft)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/staff/knowledge/versions/{versionId}", wrapper.StaffUpdateDraft)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/staff/knowledge/versions/{versionId}/submit", wrapper.StaffSubmitForReview)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/staff/knowledge/versions/{versionId}/publish", wrapper.StaffPublish)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/staff/knowledge/versions/{versionId}/reject", wrapper.StaffReject)

	return m
}

