// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /knowledge/articles/{articleId})
	GetArticle(ctx context.Context, request GetArticleRequestObject) (GetArticleResponseObject, error)

	// (GET /knowledge/topics)
	ListKnowledgeTopics(ctx context.Context, request ListKnowledgeTopicsRequestObject) (ListKnowledgeTopicsResponseObject, error)

	// (GET /knowledge/topics/{topicId}/articles)
	ListTopicArticles(ctx context.Context, request ListTopicArticlesRequestObject) (ListTopicArticlesResponseObject, error)

	// (GET /staff/knowledge/articles)
	StaffListArticles(ctx context.Context, request StaffListArticlesRequestObject) (StaffListArticlesResponseObject, error)
	// StaffCreateDraft Start a new article or a new version of an existing one (draft).
	// (POST /staff/knowledge/articles)
	StaffCreateDraft(ctx context.Context, request StaffCreateDraftRequestObject) (StaffCreateDraftResponseObject, error)

	// (GET /staff/knowledge/topics)
	StaffListTopics(ctx context.Context, request StaffListTopicsRequestObject) (StaffListTopicsResponseObject, error)
	// StaffCreateTopic Admin, psychologist (self-help) or lawyer (rights).
	// (POST /staff/knowledge/topics)
	StaffCreateTopic(ctx context.Context, request StaffCreateTopicRequestObject) (StaffCreateTopicResponseObject, error)
	// StaffUpdateDraft Edit a draft (only the author, only while draft).
	// (PUT /staff/knowledge/versions/{versionId})
	StaffUpdateDraft(ctx context.Context, request StaffUpdateDraftRequestObject) (StaffUpdateDraftResponseObject, error)
	// StaffPublish Reviewer with the matching role (lawyer for rights, psychologist for self-help) publishes; not the author. Audited.
	// (POST /staff/knowledge/versions/{versionId}/publish)
	StaffPublish(ctx context.Context, request StaffPublishRequestObject) (StaffPublishResponseObject, error)

	// (POST /staff/knowledge/versions/{versionId}/reject)
	StaffReject(ctx context.Context, request StaffRejectRequestObject) (StaffRejectResponseObject, error)

	// (POST /staff/knowledge/versions/{versionId}/submit)
	StaffSubmitForReview(ctx context.Context, request StaffSubmitForReviewRequestObject) (StaffSubmitForReviewResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

